 $st=$conn->prepare('SELECT COUNT(DISTINCT order_id), COALESCE(SUM(price*quantity),0) FROM order_items WHERE farmer_id=?'); $st->bind_param('i',$farmerId); $st->execute(); $st->bind_result($orderCount,$earnings); $st->fetch(); $st->close();
 $st=$conn->prepare('SELECT p_name, price, stock_quantity, category FROM products WHERE farmer_id=? ORDER BY stock_quantity ASC, p_name ASC LIMIT 5'); $st->bind_param('i',$farmerId); $st->execute(); $topProducts=$st->get_result()->fetch_all(MYSQLI_ASSOC); $st->close();
}
